const dark=document.createElement('link');dark.rel='stylesheet';dark.href='dark.css';document.head.append(dark);
const $=id=>document.getElementById(id);let threadId=null,turnId=null,cursor=0,busy=false,polling=false;const items=new Map(),shown=new Set();$('project').value=localStorage.getItem('hub-codex-project')||'';const model=document.createElement('select');model.id='model';model.setAttribute('aria-label','Codex model');for(const id of ['gpt-6-astra','gpt-6-sol','gpt-6-luna','gpt-5.6-sol','gpt-5.6-terra','gpt-5.6-luna','gpt-5.5']){const o=document.createElement('option');o.value=id;o.textContent=id;model.append(o)}const savedModel=localStorage.getItem('hub-codex-model');if([...model.options].some(o=>o.value===savedModel))model.value=savedModel;model.onchange=()=>localStorage.setItem('hub-codex-model',model.value);$('status').after(model);
async function post(route,data){if(route==='rpc'&&['thread/start','thread/resume'].includes(data.method))data.params={...data.params,model:model.value};const r=await fetch('/hub/'+route,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const b=await r.json();if(!r.ok||b.error)throw Error(b.error||'Local Codex bridge unavailable. Open the local workspace.');return b}const rpc=(method,params)=>post('rpc',{method,params});function error(e){$('error').textContent=e.message;busy=false;$('send').disabled=false}function message(id,text,kind=''){let el=items.get(id);if(!el){el=document.createElement('div');el.className='message '+kind;items.set(id,el);$('messages').append(el)}el.textContent=text;$('messages').scrollTop=$('messages').scrollHeight;return el}function reset(){items.clear();shown.clear();$('messages').replaceChildren();$('approvals').replaceChildren()}
async function list(){const r=await rpc('thread/list',{limit:30,archived:false});$('threads').replaceChildren();for(const t of r.data||[]){const b=document.createElement('button');b.textContent=t.name||t.preview||'Untitled chat';b.title=b.textContent;b.onclick=()=>open(t.id);$('threads').append(b)}}async function open(id){if(busy)return;try{$('status').textContent='Opening chat…';const r=await rpc('thread/resume',{threadId:id});threadId=r.thread.id;reset();for(const turn of r.thread.turns||[])for(const item of turn.items||[]){if(item.type==='userMessage')message(item.id,(item.content||[]).filter(x=>x.type==='text').map(x=>x.text).join('\n'),'user');else if(item.type==='agentMessage')message(item.id,item.text||'');else if(item.type==='commandExecution')message(item.id,item.command||'Command','small')}$('status').textContent='Connected · ready'}catch(e){error(e)}}async function create(){const cwd=$('project').value.trim();if(!cwd)throw Error('Enter a project folder.');const r=await rpc('thread/start',{cwd});threadId=r.thread.id;reset();localStorage.setItem('hub-codex-project',cwd);$('status').textContent='Connected · new chat';await list()}
$('new').onclick=()=>{if(!busy)create().catch(error)};$('refresh').onclick=()=>list().catch(error);$('compose').onsubmit=async e=>{e.preventDefault();if(busy)return;const text=$('prompt').value.trim();if(!text)return;try{$('error').textContent='';busy=true;$('send').disabled=true;if(!threadId)await create();message('user-'+Date.now(),text,'user');$('prompt').value='';const r=await rpc('turn/start',{threadId,input:[{type:'text',text}]});turnId=r.turn.id;$('stop').disabled=false;$('status').textContent='Codex is working…'}catch(e){error(e)}};$('stop').onclick=()=>rpc('turn/interrupt',{threadId,turnId}).catch(error);$('prompt').onkeydown=e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();$('compose').requestSubmit()}};
function approval(req){if(shown.has(String(req.id))||req.params?.threadId!==threadId)return;shown.add(String(req.id));const box=document.createElement('div');box.className='approval';const title=document.createElement('strong');title.textContent='Codex needs your input';const pre=document.createElement('pre');pre.textContent=JSON.stringify(req.params,null,2);box.append(title,pre);if(['item/commandExecution/requestApproval','item/fileChange/requestApproval'].includes(req.method)){for(const decision of ['accept','decline']){const b=document.createElement('button');b.textContent=decision==='accept'?'Approve once':'Decline';b.onclick=()=>post('answer',{id:req.id,result:{decision}}).then(()=>box.remove()).catch(error);box.append(b)}}else if(req.method==='tool/requestUserInput'){const inputs=[];for(const q of req.params.questions||[]){const label=document.createElement('label');label.textContent=q.question;const input=document.createElement('input');input.placeholder=(q.options||[]).map(o=>o.label).join(' / ')||'Your answer';inputs.push({id:q.id,input});box.append(label,input)}const send=document.createElement('button');send.textContent='Submit answers';send.onclick=()=>{const answers=Object.fromEntries(inputs.map(x=>[x.id,{answers:[x.input.value]}]));post('answer',{id:req.id,result:{answers}}).then(()=>box.remove()).catch(error)};box.append(send)}else{const hint=document.createElement('p');hint.textContent='This request type is not supported here. Stop this turn and continue in the desktop app.';box.append(hint)}$('approvals').append(box)}
async function poll(){if(polling)return;polling=true;try{const r=await fetch('/hub/events?after='+cursor);const data=await r.json();for(const event of data.events||[]){cursor=Math.max(cursor,event.seq);const p=event.params||{};if(p.threadId&&p.threadId!==threadId)continue;if(event.id!==undefined&&event.method){approval(event);continue}if(event.method==='item/agentMessage/delta'){const old=items.get(p.itemId)?.textContent||'';message(p.itemId,old+(p.delta||''))}if(event.method==='item/completed'&&p.item?.type==='agentMessage')message(p.item.id,p.item.text||'');if(event.method==='item/started'&&p.item?.type==='commandExecution')message(p.item.id,p.item.command||'Running a command…','small');if(event.method==='turn/completed'){busy=false;turnId=null;$('send').disabled=false;$('stop').disabled=true;$('status').textContent='Connected · '+(p.turn?.status||'ready');if(p.turn?.error)error(Error(p.turn.error.message))}if(event.method==='error')error(Error(p.message||p.error?.message||'Codex error'));if(event.method==='bridge/disconnected')error(Error('Codex disconnected. Reload this tab to reconnect.'))}for(const req of data.pending||[])approval(req)}catch(e){$('status').textContent='Local bridge unavailable'}finally{polling=false}}
(async()=>{try{const account=await rpc('account/read',{});if(!account.connected)throw Error('Codex needs a local sign-in. Run codex login in your terminal, then reload this tab.');$('status').textContent='Connected · local Codex';await list();setInterval(poll,800);poll()}catch(e){error(e);$('status').textContent='Not connected'}})();
